const RANK = { bajo: 0, medio: 1, alto: 2, critico: 3 };

// Esta lista replica los cuatro modelos configurados hoy en los combos de
// OmniRoute. Si un combo cambia, actualizar esta lista en el mismo cambio.
const ESFUERZO_POR_MODELO = {
  'nvidia/meta/llama-3.1-8b-instruct': 'bajo',
  'meta/llama-3.1-8b-instruct': 'bajo',
  'nvidia/nvidia/llama-3.3-nemotron-super-49b-v1.5': 'medio',
  'nvidia/llama-3.3-nemotron-super-49b-v1.5': 'medio',
  'nvidia/nvidia/nemotron-3-super-120b-a12b': 'alto',
  'nvidia/nemotron-3-super-120b-a12b': 'alto',
  'nvidia/nvidia/nemotron-3-ultra-550b-a55b': 'critico',
  'nvidia/nemotron-3-ultra-550b-a55b': 'critico'
};

const tarea = $('Reclamar tarea pendiente').first().json;
const esfuerzoSolicitado = $('Obtener esfuerzo fijo del bot').first().json.esfuerzo_fijo || tarea.esfuerzo;
const modeloUsado = $('Llamar a omniroute').first().json.model;
const esfuerzoUsado = ESFUERZO_POR_MODELO[modeloUsado];

// OmniRoute no expone en el body el paso del combo que ejecutó. Un modelo
// desconocido no permite confirmar que respetó el nivel, así que se avisa sin
// bloquear la tarea ni convertirla en fallo.
if (!esfuerzoUsado) {
  return [{ json: {
    tipo: 'modelo_desconocido',
    task_id: tarea.id,
    bot: tarea.bot,
    esfuerzo_solicitado: esfuerzoSolicitado,
    modelo_usado: modeloUsado || '(sin modelo en respuesta)'
  } }];
}

if (RANK[esfuerzoUsado] < RANK[esfuerzoSolicitado]) {
  return [{ json: {
    tipo: 'degradacion',
    task_id: tarea.id,
    bot: tarea.bot,
    esfuerzo_solicitado: esfuerzoSolicitado,
    esfuerzo_usado: esfuerzoUsado,
    modelo_usado: modeloUsado
  } }];
}

return [];

