const CAP_POR_ESFUERZO = {
  bajo:    { porDespacho: 5,  porOperacion: 50  },
  medio:   { porDespacho: 10, porOperacion: 100 },
  alto:    { porDespacho: 15, porOperacion: 150 },
  critico: { porDespacho: 20, porOperacion: 200 }
};

const salida = JSON.parse($('Llamar a omniroute').first().json.choices[0].message.content);
const tareaPadre = $('Reclamar tarea pendiente').first().json;
const parentId = tareaPadre.id;
const clusterPropio = $('Obtener config del bot').first().json.cluster;
const operationId = tareaPadre.operation_id;
const totalOperacion = $('Contar tareas de operacion').first().json.total;
// Este valor es la preferencia actual de la operacion y puede cambiarse desde la interfaz.
// No es un minimo ni se hereda automaticamente: cada center asigna el esfuerzo de la tarea concreta.
const esfuerzoOperacion = $('Contar tareas de operacion').first().json.esfuerzo_operacion || tareaPadre.esfuerzo;
const botsRequierenAprobacion = $('Obtener bots que requieren aprobacion').first().json.slugs || [];
const botPropio = tareaPadre.bot;
const cap = CAP_POR_ESFUERZO[esfuerzoOperacion] || CAP_POR_ESFUERZO.bajo;
const asignaciones = salida.asignaciones || [];

if (operationId && totalOperacion >= cap.porOperacion) {
  return [{ json: { _tipo: 'tope_operacion', operation_id: operationId, total_actual: totalOperacion, tope: cap.porOperacion, bot: botPropio } }];
}

const truncadas = Math.max(0, asignaciones.length - cap.porDespacho);
const items = asignaciones.slice(0, cap.porDespacho).map(a => {
  const esfuerzo = a.esfuerzo || esfuerzoOperacion;
  const requiereAprobacion = a.requiere_aprobacion === true || botsRequierenAprobacion.includes(a.bot);
  return { json: {
    _tipo: requiereAprobacion ? 'requiere_aprobacion' : 'normal',
    cluster: a.cluster || clusterPropio,
    bot: a.bot,
    status: 'pending',
    input: { text: a.input, modo: a.modo },
    parent_task_id: parentId,
    esfuerzo,
    operation_id: operationId
  } };
});

if (truncadas > 0) {
  items.push({ json: { _tipo: 'fanout_truncado', operation_id: operationId, truncadas, tope: cap.porDespacho, bot: botPropio } });
}

return items;

const cfg = $('Obtener config del bot').first().json;
if (!cfg.conocimiento_directo) return [];
let out;
try { out = JSON.parse($('Llamar a omniroute').first().json.choices[0].message.content); }
catch (e) { return []; }
const p = out.patron_aprendido;
if (!p || !p.patron) return [];
const tarea = $('Reclamar tarea pendiente').first().json;
return [{ json: {
  titulo: String(p.patron).slice(0, 200),
  resumen_corto: p.causa_raiz || '',
  detalle_completo: p.fix || '',
  cluster: tarea.cluster,
  origen_bot: tarea.bot,
  task_id: tarea.id
}}];

const taskId = $('Reclamar tarea pendiente').item.json.id;

let errMsg;
if (typeof $json.error === 'string') {
  errMsg = $json.error;
} else if ($json.error && typeof $json.error === 'object') {
  errMsg = $json.error.message || $json.error.description || JSON.stringify($json.error);
} else if ($json.message) {
  errMsg = $json.message;
} else {
  errMsg = JSON.stringify($json);
}

return [{ json: { taskId, errMsg } }];
